design.compositionCss:
/* Red Pencil: original projection proof-sheet composition. */
.shell{display:block}
.sidebar{display:grid;grid-template-columns:180px minmax(0,1fr);gap:18px 26px;padding:24px 4vw;border-bottom:12px solid var(--weekly-mark);height:auto}
.brand{margin:0;align-self:start;border-top:2px solid var(--acid);padding-top:14px}
.sidebar nav{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:7px}
.nav-item{display:flex;flex-direction:column;align-items:start;gap:10px;min-height:80px;padding:12px 9px;border:1px solid var(--acid);border-bottom:5px solid var(--acid);font-size:10px}
.nav-item span{font-family:var(--condensed);font-size:30px;line-height:1}
.sidebar-foot{grid-column:1/-1;flex-wrap:wrap;gap:8px}
main{max-width:1660px;padding:0 4vw 80px;margin:auto}
.topbar{min-height:170px;padding:36px 0;border-bottom:2px solid var(--ink)}
.topbar h1{font-family:var(--display);font-size:clamp(48px,5.5vw,82px);line-height:1.02;letter-spacing:-.07em;max-width:1100px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:590px;padding:46px;border:2px solid var(--acid);border-left:18px solid var(--weekly-mark)}
.poster-focus h2{font-family:var(--display);font-size:clamp(78px,9.8vw,140px);line-height:1.03;letter-spacing:-.08em;max-width:950px}
.poster-focus h2 span{border-bottom:5px solid var(--weekly-mark);padding-bottom:10px;max-width:100%}
.poster-focus .hero-script{font-size:35px!important;margin:20px 0}
.poster-focus .cinema-scene{width:48%;right:0;top:8%;opacity:.45;transform:rotate(-3deg)}
.hero-grid .stat-card{grid-column:auto;grid-row:auto;display:flex;flex-direction:column;align-items:start;min-height:160px;padding:24px;border:1px solid var(--ink);border-top:8px solid var(--weekly-mark);background:var(--panel);box-shadow:none}
.hero-grid .stat-card strong{font-family:var(--condensed);font-style:normal;font-size:68px;line-height:1;margin:12px 0}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;border:0;margin:28px 0}
.studio-programme button{border:1px solid var(--ink)!important;border-top:6px solid var(--weekly-mark)!important;padding:24px!important;min-height:122px;background:var(--weekly-soft)}
.studio-programme span{font-family:var(--display);font-size:23px;line-height:1.2;letter-spacing:-.05em}
.panel h2,.intro-panel h2{font-family:var(--display);line-height:1.15;letter-spacing:-.055em}
.panel,.module,.phase,.evidence-card{box-shadow:none}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.module{padding:28px;border:1px solid var(--ink);border-top:7px solid var(--weekly-mark)}
.module h3{font-family:var(--display);font-size:31px;letter-spacing:-.055em;line-height:1.15}
.module-head small{font-size:19px}
.roadmap{display:grid;columns:auto;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.phase:nth-child(n){margin:0!important;padding:26px;min-height:280px;border:1px solid var(--ink);border-top:7px solid var(--weekly-mark)}
.phase h3{font-family:var(--condensed);font-size:35px;line-height:1.1;letter-spacing:0}
.resource-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.resource{display:grid;grid-template-columns:minmax(0,1fr);gap:16px;padding:27px;border:1px solid var(--ink);border-left:9px solid var(--weekly-mark);box-shadow:none}
.resource h3{font-family:var(--display);font-size:21px;line-height:1.25;letter-spacing:-.04em}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.evidence-card{border:1px solid var(--ink);border-left:7px solid var(--weekly-mark);padding:24px}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px;border:0}
.cinema-film{padding:24px;border:1px solid var(--ink);border-top:8px solid var(--weekly-mark);box-shadow:none}
.film-cover{min-height:350px;border:1px solid var(--ink);border-bottom:8px solid var(--weekly-mark);background:var(--weekly-soft)}
.cinema-film .film-cover h3{font-family:var(--display);font-size:48px;line-height:1.08;letter-spacing:-.065em}
.journal-masthead{border-bottom:8px solid var(--weekly-mark);padding-bottom:32px}
.journal-masthead h2{font-family:var(--script);font-size:clamp(88px,10.5vw,140px);line-height:1.08;letter-spacing:-.065em}
.journal-masthead h2 em{font-family:var(--display);font-style:normal;font-size:.68em;line-height:1.1}
.journal-workbench{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:28px}
.journal-workbench :is(.form-panel,.journal-bridge){border-top:7px solid var(--weekly-mark)}
#view-journal .journal-deck{gap:24px}
.diary-card:not(.poster-card){border:1px solid var(--ink);border-top:7px solid var(--weekly-mark);padding:24px;transform:none;box-shadow:none}
.journal-section-title{border-top:7px solid var(--weekly-mark)}
@media(max-width:1100px) and (min-width:761px){
.sidebar{grid-template-columns:150px minmax(0,1fr)}
.sidebar nav{grid-template-columns:repeat(4,minmax(0,1fr))}
.roadmap{grid-template-columns:repeat(2,minmax(0,1fr))}
.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:760px){
.sidebar{display:block;padding:20px;border-bottom-width:8px}
.brand{border:0;padding:0}
main{padding:0 20px 64px}
.topbar{min-height:0;padding:26px 0}
.topbar h1{font-size:42px;line-height:1.07;letter-spacing:-.06em}
.poster-focus{min-height:530px;padding:28px 22px;border:1px solid var(--acid);border-left:8px solid var(--weekly-mark)}
.poster-focus h2{font-size:clamp(58px,16vw,88px);line-height:1.07;letter-spacing:-.075em}
.poster-focus .hero-script{font-size:27px!important}
.poster-focus .cinema-scene{width:70%;right:-10%;opacity:.3}
.hero-grid .stat-card{min-height:136px;padding:15px 9px;border-top-width:5px}
.hero-grid .stat-card strong{font-size:38px;margin:12px 0 6px}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:20px}
.studio-programme button{min-height:106px;padding:22px!important}
.studio-programme span{font-size:22px}
.module,.phase:nth-child(n),.resource,.evidence-card,.cinema-film{padding:22px}
.module h3{font-size:27px}
.phase:nth-child(n){min-height:0}
.phase h3{font-size:31px}
.film-cover{min-height:300px}
.cinema-film .film-cover h3{font-size:38px;line-height:1.1}
#view-journal .journal-masthead h2{font-size:clamp(50px,14vw,78px);line-height:1.15;overflow-wrap:anywhere}
#view-journal .journal-masthead h2 em{font-size:.8em;line-height:1.15}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:not(.poster-card){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:36px 14px}
#view-journal .journal-empty h3{font-size:42px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
